const boats=[{name:'Houseboats',image:'houseboat',description:'Modern, stylish and fully customisable for extended stays.'},{name:'Leisure boats',image:'leisure',description:'Perfect for family time, weekends and relaxing on the water.'},{name:'Entertainment boats',image:'entertainment',description:'Designed for socialising, events and unforgettable experiences.'},{name:'Commercial / custom',image:'commercial',description:'Built to your unique requirements and specifications.'}];
const quote=document.querySelector('#quote'),gallery=document.querySelector('#gallery'),story=document.querySelector('#story');let currentBoat=0,heroSlide=0;
function openQuote(index){if(gallery.open)gallery.close();if(story.open)story.close();if(Number.isInteger(index))document.querySelector('[name="boat"]').selectedIndex=index;document.querySelector('#form-status').textContent='';quote.showModal()}
document.querySelectorAll('[data-quote]').forEach(button=>button.addEventListener('click',()=>openQuote()));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()}})});
function updateGallery(){const boat=boats[currentBoat];document.querySelector('#gallery-title').textContent=boat.name;document.querySelector('#gallery-image').src=`assets/${boat.image}.webp`;document.querySelector('#gallery-image').alt=boat.name;document.querySelector('#gallery-description').textContent=boat.description;document.querySelector('#gallery-counter').textContent=`${currentBoat+1} / ${boats.length}`}
function showGallery(index=0){currentBoat=index;updateGallery();gallery.showModal()}
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>showGallery()));document.querySelectorAll('[data-boat]').forEach(button=>button.addEventListener('click',()=>showGallery(Number(button.dataset.boat))));
document.querySelector('#gallery-prev').addEventListener('click',()=>{currentBoat=(currentBoat+3)%4;updateGallery()});document.querySelector('#gallery-next').addEventListener('click',()=>{currentBoat=(currentBoat+1)%4;updateGallery()});document.querySelector('#gallery-quote').addEventListener('click',()=>openQuote(currentBoat));
document.querySelector('[data-story]').addEventListener('click',()=>story.showModal());document.querySelector('#story-quote').addEventListener('click',()=>openQuote());
document.querySelectorAll('[data-slide]').forEach(button=>button.addEventListener('click',()=>{heroSlide=(heroSlide+Number(button.dataset.slide)+5)%5;const photo=document.querySelector('.hero-photo');photo.style.backgroundImage=`url('assets/${heroSlide===0?'hero':boats[heroSlide-1].image}.webp')`;photo.style.backgroundSize=heroSlide===0?'100% 100%':'cover';photo.style.backgroundPosition=heroSlide===0?'center':'65% center';}));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const opened=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(opened));menu.setAttribute('aria-label',opened?'Close menu':'Open menu');menu.textContent=opened?'×':'☰'});nav.querySelectorAll('a,button').forEach(item=>item.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';menu.setAttribute('aria-label','Open menu')}));
document.querySelector('#quote-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const content=['MK LEISURE — CUSTOM BOAT ENQUIRY','',...['name','email','phone','boat','timeline','budget','vision'].map(key=>`${key[0].toUpperCase()+key.slice(1)}: ${data.get(key)||'Not provided'}`),'','Prepared for sharing with MK Leisure. This enquiry has not been sent.'].join('\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='mk-leisure-boat-enquiry.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your enquiry is ready to download. Share the file with the MK Leisure team to request a quote.'});
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${entry.target.id}`))}}),{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('main section[id]').forEach(section=>observer.observe(section))}
